Promise.delay = function (time) {
  return new Promise((resolve, reject) => {
    setTimeout(resolve, time)
  })
};

Promise.prototype.takeAtLeast = function (time) {
  return new Promise((resolve, reject) => {
    Promise.all([this, Promise.delay(time)]).then(([result]) => {
      resolve(result)
    }, reject)
  })
};

